U_at = [None] * n_nodes
cnt_at = [None] * n_nodes
tsum_at = [None] * n_nodes
for node in range(n_nodes):
    buckets = [[] for _ in range(ngroups)]
    for level, gain in per_node[node]:
        buckets[level].append(gain)
    Uarr = [None] * (ngroups + 1)
    carr = [0] * (ngroups + 1)
    tarr = [0] * (ngroups + 1)
    cur = []
    total = 0
    Uarr[ngroups] = (0,)
    for level in range(ngroups - 1, -1, -1):
        if buckets[level]:
            cur.extend(buckets[level])
            cur.sort(reverse=True)
            total = 0
            prefix = [0]
            for value in cur:
                total += value
                prefix.append(total)
            Uarr[level] = tuple(prefix)
        else:
            Uarr[level] = Uarr[level + 1]
        carr[level] = len(cur)
        tarr[level] = total
    U_at[node] = Uarr
    cnt_at[node] = carr
    tsum_at[node] = tarr

last_level = [-1] * n_nodes
for level, group in enumerate(glist):
    for node in group[0]:
        last_level[node] = level
active = [tuple(node for node in range(n_nodes) if last_level[node] >= level)
          for level in range(ngroups + 1)]

best = [0, 0, 0]
memo = {}
used = [0] * n_nodes

def consider(total_b, total_c, mask):
    if total_b > best[0] or (total_b == best[0] and total_c < best[1]):
        best[0] = total_b
        best[1] = total_c
        best[2] = mask

def rec(level, acc_b, acc_c, mask):
    if level == ngroups:
        consider(acc_b, acc_c, mask)
        return 0, 0, 0, True
    nodes_here = active[level]
    if nodes_here:
        key = (level, tuple([used[node] for node in nodes_here]))
    else:
        key = (level, ())
    hit = memo.get(key)
    if hit is not None:
        got_b, got_c, got_mask = hit
        consider(acc_b + got_b, acc_c + got_c, mask | got_mask)
        return got_b, got_c, got_mask, True
    limit = suffix = suf[level]
    for node in nodes_here:
        avail = slots[node] - used[node]
        total = tsum_at[node][level]
        if avail <= 0:
            bound = suffix - total
        else:
            cnt = cnt_at[node][level]
            table = U_at[node][level]
            pick = avail if avail < cnt else cnt
            bound = table[pick] + suffix - total
        if bound < limit:
            limit = bound
        if limit <= 0:
            break
    if acc_b + limit < best[0] or (acc_b + limit == best[0] and acc_c >= best[1]):
        consider(acc_b, acc_c, mask)
        return 0, 0, 0, False
    nodes, pre, masks, size = glist[level]
    cap = size
    for node in nodes:
        avail = slots[node] - used[node]
        if avail < cap:
            cap = avail
    best_value = None
    exact = True
    for take in range(cap, -1, -1):
        if take:
            for node in nodes:
                used[node] += take
        got_b, got_c, got_mask, got_exact = rec(level + 1, acc_b + pre[take],
                                                acc_c + take,
                                                mask | masks[take])
        if take:
            for node in nodes:
                used[node] -= take
        if not got_exact:
            exact = False
        value = (got_b + pre[take], got_c + take, got_mask | masks[take])
        if best_value is None or (value[0], -value[1]) > (best_value[0], -best_value[1]):
            best_value = value
    if exact and len(memo) < MEMO_CAP:
        memo[key] = best_value
    consider(acc_b + best_value[0], acc_c + best_value[1],
             mask | best_value[2])
    return best_value[0], best_value[1], best_value[2], exact

